commands.command:
set -eu
cat > /tmp/nftables.conf.ssh-rate-limit <<'ANTRIEB_NFT_EOF'
#!/usr/bin/nft -f

flush ruleset

table inet ssh_guard {
  chain input {
    type filter hook input priority filter; policy accept;

    ct state new tcp dport 22 tcp flags & (fin | syn | rst | ack) == syn meter ssh_ipv4 { ip saddr timeout 1m limit rate over 6/minute burst 4 packets } counter drop comment "rate-limit repeated IPv4 SSH connections"
    ct state new tcp dport 22 tcp flags & (fin | syn | rst | ack) == syn meter ssh_ipv6 { ip6 saddr timeout 1m limit rate over 6/minute burst 4 packets } counter drop comment "rate-limit repeated IPv6 SSH connections"
  }
}
ANTRIEB_NFT_EOF
nft -c -f /tmp/nftables.conf.ssh-rate-limit
printf 'nft_syntax_check=ok\n'
sed -n '1,80p' /tmp/nftables.conf.ssh-rate-limit

